fields.ValueConv:
return 0 unless $val;
$val = -3 if $val == 29;  # -3 is stored as 0x1d
return 2**($val/16 + 4);

fields.ValueConvInv:
return 0 unless $val;
my $raw = int((log($val)/log(2)-4)*16+0.5);
$raw = 29 if $raw < 0;   # guide number of 14 gives -3 which is stored as 0x1d
$raw = 31 if $raw > 31;  # maximum value is 0x1f
return $raw;

fields.PrintConv:
my @a = split ' ', $val;
my $f = shift @a;
return 'Off' unless $f;
my $mask = 0x10;
my @rtn;
foreach ('R','G','B') {
    my $b = shift @a;
    $b = -$b if $f & $mask;
    $mask <<= 1;
    push @rtn, sprintf("$_%+d%%", $b);
}
return \@rtn;

fields.ValueConvInv:
my $range = int(log($val/10)/(2*log(2)));
warn("Value out of range") and return undef if $range < 0 or $range > 3;
return $range + (int($val/(10*4**($range-2))+0.5) << 2);

fields.ValueConv:
my @v = split(' ',$val);
$v[0] &= 0x0f;
$v[1] = $v[2] * 256 + $v[3]; # (always high byte first)
return "$v[0] $v[1]";

fields.ValueConvInv:
my @v = split(' ',$val);
return undef unless @v == 2;
$v[2] = ($v[1] >> 8) & 0xff;
$v[3] = $v[1] & 0xff;
$v[1] = 0;
return "@v";

